from PIL import Image
def load(p): return Image.open(p).convert("L")
im2=load("captures/side_002.jpg")
im3=load("captures/side_003.jpg")
w,h=im2.size
d2=list(im2.getdata())
d3=list(im3.getdata())
# platen center x 310-330? Let's use x 315-325 average, scan y 180-210
def vprof(data,x0,x1,y0,y1):
    for y in range(y0,y1):
        s=sum(data[y*w+x] for x in range(x0,x1))/(x1-x0)
        yield y,s
print("im2 platen center")
for y,s in vprof(d2,315,325,180,215):
    print(y, f"{s:.1f}")
print("im3 platen center")
for y,s in vprof(d3,315,325,180,215):
    print(y, f"{s:.1f}")
